package learning

import "mentorforge-ai/backend-go/internal/domain"

func seedGoCollectionsQuestions() []domain.Question {
	return []domain.Question{
		newQuestion(31, 1, "beginner", "Что такое условие и какой тип должен иметь его результат?",
			"Условие — это выражение типа bool со значением true или false.",
			"Условие управляет выполнением ветки кода и в Go обязательно имеет тип bool. Его часто получают через сравнение или логические операторы.",
			"Условия проверяют обязательные поля HTTP-запроса, допустимые уровни и другие ограничения входных данных.",
			[]string{"Какие значения есть у bool?", "Чем && отличается от ||?"}, "Запишите простую bool-проверку допустимого уровня."),
		newQuestion(32, 1, "beginner", "Как работают if, else if и else?",
			"if проверяет первое условие, else if — дополнительные условия, а else выполняется, если ни одно условие не подошло.",
			"Ветки проверяются сверху вниз. Выполняется блок первого истинного условия; else служит запасной веткой. Условия имеют тип bool, круглые скобки не нужны, фигурные обязательны.",
			"Ветвление выбирает код ответа, способ обработки или понятное сообщение для разных вариантов входных данных.",
			[]string{"Может ли быть несколько else if?", "Когда ветка else не нужна?"}, "Опишите три ветки для некорректного, начального и повышенного уровня."),
		newQuestion(33, 1, "beginner", "Почему в Go нет отдельного ключевого слова while?",
			"Потому что for в Go поддерживает и цикл со счётчиком, и цикл только с условием.",
			"Go использует одно ключевое слово for для разных форм циклов. Запись for condition { ... } выполняет роль while, а for { ... } создаёт бесконечный цикл.",
			"Цикл только с условием используют, когда число повторений заранее неизвестно, например при чтении последовательности входных событий.",
			[]string{"Как записать бесконечный цикл?", "Чем break отличается от continue?"}, "Перепишите воображаемый while через for с условием."),
		newQuestion(34, 1, "beginner", "Чем массив отличается от slice?",
			"Массив имеет фиксированную длину, которая входит в его тип, а slice удобнее для последовательности изменяемой длины.",
			"Тип массива включает длину, например [3]string. Slice записывается как []string, представляет последовательность элементов одного типа и обычно используется в прикладном коде чаще массива.",
			"Slice хранит списки результатов, карточек и других однотипных значений, количество которых заранее неизвестно.",
			[]string{"Что возвращает len для slice?", "Почему [3]int и [4]int — разные типы?"}, "Создайте slice из трёх нейтральных названий карточек."),
		newQuestion(35, 1, "beginner", "Зачем результат append обычно присваивают обратно в переменную?",
			"append возвращает обновлённый slice, поэтому пишут cards = append(cards, newCard).",
			"append не изменяет переменную slice автоматически: функция возвращает новое значение slice и при необходимости может связать его с другой областью хранения. Результат нужно сохранить.",
			"append используют при накоплении результатов фильтрации, формировании ответа и добавлении элементов в список.",
			[]string{"Можно ли append добавить несколько элементов?", "Как len изменяется после append одного элемента?"}, "Добавьте строку в slice и сохраните результат append."),
		newQuestion(36, 1, "beginner", "Какие значения возвращает range при обходе slice?",
			"range для slice возвращает индекс и копию значения элемента.",
			"В for index, value := range items первое значение — индекс, второе — копия элемента. Ненужное значение заменяют на _, а для изменения элемента обычно обращаются через items[index].",
			"range последовательно обходит списки результатов, карточек и других коллекций без ручного управления индексом.",
			[]string{"Как игнорировать индекс?", "Почему для изменения struct в slice часто используют индекс?"}, "Покажите три формы range: с индексом и значением, только со значением и только с индексом."),
		newQuestion(37, 1, "beginner", "Что такое map и чем ключ отличается от значения?",
			"Map хранит пары: ключ используется для поиска, а значение содержит связанные данные.",
			"Map задаёт единый тип ключей и единый тип значений, например map[string]StudyCard. Ключ уникально определяет запись, а значение можно прочитать или заменить по этому ключу.",
			"Map используют для индексов быстрого поиска, конфигурации, кэша и группировки значений.",
			[]string{"Как создать map через make?", "Как удалить элемент map?"}, "Опишите тип map, где название карточки связано с её уровнем."),
		newQuestion(38, 1, "beginner", "Как проверить, существует ли ключ в map?",
			"Нужно получить значение и bool: card, ok := cards[title], затем проверить ok.",
			"Дополнительный результат ok равен true, если ключ найден, и false, если его нет. Значение при отсутствии ключа будет нулевым, поэтому только его проверки недостаточно.",
			"value, ok безопасно обрабатывает необязательные настройки, элементы кэша и запросы поиска по ключу.",
			[]string{"Что содержит value при отсутствующем ключе?", "Почему нулевое значение не доказывает отсутствие ключа?"}, "Запишите безопасный поиск строки в map с отдельной проверкой ok."),
		newQuestion(39, 1, "beginner", "Гарантирован ли порядок обхода map?",
			"Нет, порядок обхода map через range не гарантируется.",
			"На порядок range по map нельзя полагаться: он не обязан совпадать с порядком добавления. Для стабильного результата ключи собирают в slice, сортируют и затем читают значения по ним.",
			"Это важно для предсказуемых отчётов, ответов API и тестов, где требуется стабильный порядок элементов.",
			[]string{"Что делать, если нужен стабильный порядок?", "Подходит ли map как единственное хранилище упорядоченного списка?"}, "Объясните одним предложением, почему вывод map нельзя сравнивать по порядку без дополнительной обработки."),
	}
}
